const items = $input.all();

const documentFields = [
  { field: "Balance Sheet", type: "balance_sheet" },
  { field: "Income Statement", type: "income_statement" },
  { field: "Cash Flow Statement", type: "cash_flow_statement" }
];

const extensionTypes = {
  pdf: "pdf",
  png: "image",
  jpg: "image",
  jpeg: "image",
  xlsx: "spreadsheet",
  csv: "spreadsheet"
};

const output = [];

for (let inputIndex = 0; inputIndex < items.length; inputIndex++) {
  const item = items[inputIndex];
  const form = item.json;
  const originalBinary = item.binary || {};

  const uploadedFiles = [];

  // Collect every uploaded file
  for (const doc of documentFields) {
    const files = form[doc.field];

    if (!Array.isArray(files)) continue;

    for (let fileIndex = 0; fileIndex < files.length; fileIndex++) {
      const file = files[fileIndex];

      const filename = file.filename || "";
      const extension = filename.includes(".")
        ? filename.split(".").pop().toLowerCase()
        : "";

      const fileType = extensionTypes[extension] || "unsupported";

      // Matches Form Trigger binary properties:
      // Balance_Sheet_0, Balance_Sheet_1, etc.
      const binaryKey =
        doc.field.replace(/\s+/g, "_") + "_" + fileIndex;

      uploadedFiles.push({
        documentType: doc.type,
        formField: doc.field,
        filename,
        extension,
        fileType,
        mimeType: file.mimetype || "",
        sizeBytes: file.size || 0,

        // New binary reference fields
        binaryKey,
        binaryFieldName: binaryKey,
        fileIndex,
        binaryAvailable: !!originalBinary[binaryKey]
      });
    }
  }

  const totalFiles = uploadedFiles.length;

  const counts = {
    balance_sheet: 0,
    income_statement: 0,
    cash_flow_statement: 0
  };

  for (const file of uploadedFiles) {
    counts[file.documentType]++;
  }

  // Output one item per file
  for (let i = 0; i < uploadedFiles.length; i++) {
    const file = uploadedFiles[i];

    const extractionMethod =
      file.fileType === "image" ? "vision" :
      file.fileType === "pdf" ? "pdf" :
      file.fileType === "spreadsheet" ? "spreadsheet" :
      "unsupported";

    output.push({
      json: {
        ...file,

        fileNumber: i + 1,
        totalFiles,
        multipleFiles: totalFiles > 1,

        documentFileCount: counts[file.documentType],

        hasBalanceSheet: counts.balance_sheet > 0,
        hasIncomeStatement: counts.income_statement > 0,
        hasCashFlowStatement: counts.cash_flow_statement > 0,

        needsVision: file.fileType === "image",
        extractionMethod,

        submittedAt: form.submittedAt || null
      },
      pairedItem: {
        item: inputIndex
      }
    });
  }
}

return output;

const currentItem = $input.item;

// Original binary key from Form Input Parser
const binaryKey = currentItem.json.binaryKey;

// Get original form submission binaries
const formBinary = $("On form submission").first().binary || {};

// Try the exact key first
let selectedKey = binaryKey;
let selectedBinary = formBinary[selectedKey];

// If not found, try removing the trailing _0
if (!selectedBinary && binaryKey.endsWith("_0")) {
  selectedKey = binaryKey.slice(0, -2);
  selectedBinary = formBinary[selectedKey];
}

// If still not found, throw an error
if (!selectedBinary) {
  throw new Error(
    `Binary file not found for "${binaryKey}". ` +
    `Available keys: ${Object.keys(formBinary).join(", ")}`
  );
}

// Return the selected binary as "data"
return {
  json: {
    ...currentItem.json,
    binaryKey: selectedKey,
    binaryRetrieved: true
  },
  binary: {
    data: selectedBinary
  }
};

