const input = $input.item.json;

// ============================================
// 1. HELPERS
// ============================================

const warnings = [];
const errors = [];
const validations = [];

const TARGET_TYPES = [
  "balance_sheet",
  "income_statement",
  "cash_flow_statement"
];

const ALLOWED_TYPES = [
  ...TARGET_TYPES,
  "other_financial_statement"
];

const ALLOWED_STATUSES = [
  "extracted",
  "partial",
  "no_relevant_statements",
  "unreadable"
];

const ALLOWED_PERIOD_TYPES = [
  "as_of",
  "full_year",
  "quarter",
  "half_year",
  "year_to_date",
  "other",
  "unknown"
];

function unique(arr) {
  return [...new Set(arr)];
}

// Recognize alternative names for major financial totals.
// Never treat "total liabilities and equity" as equity.
const TOTAL_ALIASES = {
  total_assets: [
    "total_assets"
  ],
  total_liabilities: [
    "total_liabilities"
  ],
  total_equity: [
    "total_equity",
    "total_shareholders_equity",
    "total_stockholders_equity",
    "shareholders_equity",
    "stockholders_equity",
    "total_shareholder_equity",
    "shareholder_equity",
    "shareholders_equity_total",
    "total_equity_attributable_to_shareholders"
  ]
};

function canonicalKey(key) {
  return String(key || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");
}

function validDate(value) {
  if (typeof value !== "string") return false;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;

  const date = new Date(value + "T00:00:00Z");

  return !Number.isNaN(date.getTime()) &&
    date.toISOString().slice(0, 10) === value;
}

function parseNumber(value) {
  if (
    value === null ||
    value === undefined ||
    value === ""
  ) {
    return { value: null, valid: true };
  }

  if (typeof value === "number") {
    return {
      value: Number.isFinite(value) ? value : null,
      valid: Number.isFinite(value)
    };
  }

  if (typeof value !== "string") {
    return { value: null, valid: false };
  }

  let text = value.trim();
  const negative = /^\(.*\)$/.test(text);

  if (negative) {
    text = text.slice(1, -1).trim();
  }

  text = text.replace(/,/g, "");

  if (!/^[+-]?\d+(\.\d+)?$/.test(text)) {
    return { value: null, valid: false };
  }

  const number = Number(text);

  return {
    value: negative ? -Math.abs(number) : number,
    valid: Number.isFinite(number)
  };
}

function finish(documentStatus, statements, rejectionReason) {
  const targetStatements = statements.filter(s =>
    TARGET_TYPES.includes(s.statement_type)
  );

  const detectedTypes = unique(
    targetStatements.map(s => s.statement_type)
  );

  const accountCount = statements.reduce(
    (sum, s) => sum + s.line_items.length,
    0
  );

  const periodCount = statements.reduce(
    (sum, s) => sum + s.periods.length,
    0
  );

  const checksPassed = validations.filter(
    v => v.status === "passed"
  ).length;

  const checksFailed = validations.filter(
    v => v.status === "failed"
  ).length;

  const hasUsableData = targetStatements.some(s =>
    s.periods.length > 0 &&
    s.line_items.some(item =>
      Object.values(item.values).some(
        value => typeof value === "number"
      )
    )
  );

  let extractionStatus = "ready";

  if (documentStatus === "no_relevant_statements") {
    extractionStatus = "rejected";
  } else if (documentStatus === "unreadable") {
    extractionStatus = "unreadable";
  } else if (errors.length > 0 || !hasUsableData) {
    extractionStatus = "review_required";
  } else if (
    documentStatus === "partial" ||
    warnings.length > 0
  ) {
    extractionStatus = "review_recommended";
  }

  const extractionSuccessful =
    hasUsableData &&
    errors.length === 0 &&
    documentStatus === "extracted";

  return {
    json: {
      company: data?.company ?? null,
      documentStatus,
      containsRelevantFinancialData:
        targetStatements.length > 0,
      detectedStatementTypes: detectedTypes,
      statements,
      extractionStatus,
      extractionSuccessful,
      usableFinancialData: hasUsableData,

      summary: {
        totalStatements: statements.length,
        targetStatements: targetStatements.length,
        totalPeriods: periodCount,
        totalAccounts: accountCount,
        balanceSheets: statements.filter(
          s => s.statement_type === "balance_sheet"
        ).length,
        incomeStatements: statements.filter(
          s => s.statement_type === "income_statement"
        ).length,
        cashFlowStatements: statements.filter(
          s => s.statement_type === "cash_flow_statement"
        ).length,
        checksPassed,
        checksFailed,
        warningCount: unique(warnings).length,
        errorCount: unique(errors).length
      },

      validations,
      warnings: unique(warnings),
      errors: unique(errors),
      rejectionReason: rejectionReason || null
    }
  };
}

// ============================================
// 2. PARSE OLLAMA RESPONSE
// ============================================

let data = null;

try {
  let raw =
    input.response ??
    input.message?.content ??
    input.output ??
    input;

  if (typeof raw === "string") {
    raw = raw.trim()
      .replace(/^```(?:json)?\s*/i, "")
      .replace(/\s*```$/i, "")
      .trim();

    data = JSON.parse(raw);

    if (typeof data === "string") {
      data = JSON.parse(data);
    }
  } else {
    data = raw;
  }

  if (
    !data ||
    typeof data !== "object" ||
    Array.isArray(data)
  ) {
    throw new Error("Expected one JSON object.");
  }

} catch (error) {
  errors.push(
    "Invalid LLM JSON response: " + error.message
  );

  return finish(
    "unreadable",
    [],
    "LLM response could not be parsed."
  );
}

// ============================================
// 3. CHECK LLM GENERATION
// ============================================

const doneReason =
  input.done_reason ??
  input.doneReason ??
  null;

if (doneReason === "length") {
  errors.push("LLM reached its output token limit.");
}

if (input.done === false) {
  errors.push("LLM generation did not finish.");
}

const documentStatus = data.document_status;

if (!ALLOWED_STATUSES.includes(documentStatus)) {
  errors.push(
    `Invalid document_status: ${documentStatus}`
  );
}

if (!Array.isArray(data.statements)) {
  errors.push("Missing statements array.");

  return finish(
    "unreadable",
    [],
    "LLM output is missing its statements array."
  );
}

// ============================================
// 4. HANDLE IRRELEVANT DOCUMENTS
// ============================================

if (
  documentStatus === "no_relevant_statements" ||
  documentStatus === "unreadable"
) {
  if (data.statements.length > 0) {
    warnings.push(
      "Document marked irrelevant/unreadable but " +
      "contains statement entries. Review classification."
    );
  }

  return finish(
    documentStatus,
    [],
    data.rejection_reason ??
    "No usable financial statements identified."
  );
}

// ============================================
// 5. PROCESS EVERY FINANCIAL STATEMENT
// ============================================

const cleanedStatements = [];
let totalRawAccounts = 0;

for (const [statementIndex, statement] of
     data.statements.entries()) {

  if (!statement || typeof statement !== "object") {
    errors.push("Malformed financial statement skipped.");
    continue;
  }

  const type = statement.statement_type;

  if (!ALLOWED_TYPES.includes(type)) {
    warnings.push(
      `Unknown statement type: ${type}`
    );
    continue;
  }

  if (
    !Array.isArray(statement.periods) ||
    !Array.isArray(statement.line_items)
  ) {
    errors.push(
      `${type}: missing periods or line_items array.`
    );
    continue;
  }

  totalRawAccounts += statement.line_items.length;

  // ==========================================
  // 6. NORMALIZE REPORTING PERIODS
  // ==========================================

  const periods = [];
  const periodIDs = new Set();

  for (const period of statement.periods) {
    if (!period || typeof period !== "object") {
      warnings.push(`${type}: malformed period.`);
      continue;
    }

    const id = String(period.period_id || "").trim();

    if (!id) {
      errors.push(`${type}: missing period_id.`);
      continue;
    }

    if (periodIDs.has(id)) {
      warnings.push(
        `${type}: duplicate period ID ${id}`
      );
      continue;
    }

    const startDate = period.start_date ?? null;
    const endDate = period.end_date ?? null;

    if (startDate !== null && !validDate(startDate)) {
      errors.push(`${type}: invalid start date for ${id}`);
      continue;
    }

    if (endDate !== null && !validDate(endDate)) {
      errors.push(`${type}: invalid end date for ${id}`);
      continue;
    }

    if (startDate && endDate && startDate > endDate) {
      errors.push(`${type}: reversed dates for ${id}`);
      continue;
    }

    const periodType = period.period_type || "unknown";

    if (!ALLOWED_PERIOD_TYPES.includes(periodType)) {
      warnings.push(
        `${type}: unknown period type for ${id}`
      );
    }

    if (
      type === "balance_sheet" &&
      periodType !== "as_of"
    ) {
      warnings.push(
        `Balance sheet period ${id} is not marked as_of.`
      );
    }

    if (!endDate) {
      warnings.push(
        `${type}: missing end date for ${id}`
      );
    }

    periodIDs.add(id);

    periods.push({
      period_id: id,
      label: String(period.label || id),
      period_type: periodType,
      start_date: startDate,
      end_date: endDate
    });
  }

  // ==========================================
  // 7. VALIDATE FINANCIAL ACCOUNTS
  // ==========================================

  const lineItems = [];
  const seenKeys = new Set();

  for (const item of statement.line_items) {
    if (!item || typeof item !== "object") {
      warnings.push(`${type}: malformed account.`);
      continue;
    }

    const key = String(item.key || "").trim();

    if (!key) {
      warnings.push(`${type}: account missing key.`);
      continue;
    }

    if (seenKeys.has(key)) {
      errors.push(
        `${type}: duplicate account key "${key}".`
      );
      continue;
    }

    seenKeys.add(key);

    const values = {};
    const originalValues =
      item.values &&
      typeof item.values === "object" &&
      !Array.isArray(item.values)
        ? item.values
        : {};

    for (const period of periods) {
      const id = period.period_id;
      const result = parseNumber(originalValues[id]);

      values[id] = result.value;

      if (!result.valid) {
        warnings.push(
          `${type}: invalid value for ${key}, ${id}`
        );
      }
    }

    const unknownPeriods = Object.keys(
      originalValues
    ).filter(id => !periodIDs.has(id));

    if (unknownPeriods.length) {
      warnings.push(
        `${type}: ${key} references unknown period IDs: ` +
        unknownPeriods.join(", ")
      );
    }

    const section = String(item.section || "");
    const subsection = String(item.subsection || "");

    // Allow common names for shareholder equity.
    // "total" is also a valid section for grand totals.
    if (
      type === "balance_sheet" &&
      ![
        "assets",
        "liabilities",
        "equity",
        "shareholder_equity",
        "shareholders_equity",
        "stockholder_equity",
        "stockholders_equity",
        "total"
      ].includes(canonicalKey(section))
    ) {
      warnings.push(
        `Balance sheet account ${key} has invalid section.`
      );
    }

    lineItems.push({
      key,
      label: String(item.label || key),
      section,
      subsection,
      values,
      source_page: item.source_page ?? null
    });
  }

  if (periods.length === 0) {
    errors.push(`${type}: no valid periods.`);
  }

  if (lineItems.length === 0) {
    errors.push(`${type}: no accounts extracted.`);
  }

  // ==========================================
  // 8. FINANCIAL VALIDATION
  // ==========================================

  function getAmount(key, periodID) {
    const account = lineItems.find(
      item =>
        (TOTAL_ALIASES[key] || [key]).includes(
          canonicalKey(item.key)
        )
    );

    return account?.values?.[periodID] ?? null;
  }

  if (type === "balance_sheet") {
    for (const period of periods) {
      const id = period.period_id;

      const assets = getAmount("total_assets", id);
      const liabilities =
        getAmount("total_liabilities", id);
      const equity = getAmount("total_equity", id);

      if (
        [assets, liabilities, equity].some(
          value => value === null
        )
      ) {
        validations.push({
          statementType: type,
          periodID: id,
          check: "accounting_equation",
          status: "missing_data",
          difference: null
        });

        warnings.push(
          `Balance sheet ${id}: missing major totals.`
        );

        continue;
      }

      const difference =
        Math.round(
          (assets - liabilities - equity) * 100
        ) / 100;

      const allInteger =
        [assets, liabilities, equity].every(
          Number.isInteger
        );

      const tolerance =
        allInteger &&
        Math.max(
          Math.abs(assets),
          Math.abs(liabilities),
          Math.abs(equity)
        ) >= 1000
          ? 1
          : 0.01;

      const status =
        Math.abs(difference) < 0.000001
          ? "passed"
          : Math.abs(difference) <= tolerance
            ? "rounding_difference"
            : "failed";

      validations.push({
        statementType: type,
        periodID: id,
        check: "accounting_equation",
        totalAssets: assets,
        totalLiabilities: liabilities,
        totalEquity: equity,
        difference,
        tolerance,
        status
      });

      if (status === "rounding_difference") {
        warnings.push(
          `Balance sheet ${id}: accounting equation ` +
          `differs by ${difference} source unit(s), ` +
          `possible rounding.`
        );
      } else if (status === "failed") {
        errors.push(
          `Balance sheet ${id}: accounting equation ` +
          `failed by ${difference}.`
        );
      }
    }
  }

  // ==========================================
  // 9. STORE CLEAN STATEMENT
  // ==========================================

  cleanedStatements.push({
    statement_type: type,
    company: statement.company ?? data.company ?? null,
    currency: statement.currency ?? null,
    unit_multiplier: statement.unit_multiplier ?? null,
    periods,
    line_items: lineItems,
    warnings: Array.isArray(statement.warnings)
      ? unique(statement.warnings.map(String))
      : [],
    source_statement_index: statementIndex
  });

  if (Array.isArray(statement.warnings)) {
    warnings.push(...statement.warnings.map(String));
  }
}

// ============================================
// 10. DETECT POSSIBLE LLM REPETITION
// ============================================

if (totalRawAccounts > 1500) {
  errors.push(
    "Unusually large LLM output: possible repetition."
  );
}

if (data.statements.length > 20) {
  errors.push(
    "Unusually many financial statements returned."
  );
}

const statementSignatures = new Set();

for (const statement of cleanedStatements) {
  const signature = JSON.stringify({
    type: statement.statement_type,
    company: statement.company,
    periods: statement.periods,
    line_items: statement.line_items
  });

  if (statementSignatures.has(signature)) {
    errors.push(
      `Repeated identical ${statement.statement_type} detected.`
    );
  }

  statementSignatures.add(signature);
}

const actualTypes = unique(
  cleanedStatements
    .filter(s => TARGET_TYPES.includes(s.statement_type))
    .map(s => s.statement_type)
);

if (Array.isArray(data.detected_statement_types)) {
  const declaredTypes = unique(
    data.detected_statement_types
  );

  if (
    JSON.stringify([...declaredTypes].sort()) !==
    JSON.stringify([...actualTypes].sort())
  ) {
    warnings.push(
      "Detected statement types do not match " +
      "extracted statements."
    );
  }
}

// ============================================
// 11. FINAL CLEAN OUTPUT
// ============================================

if (cleanedStatements.length === 0) {
  errors.push("No valid financial statements extracted.");
}

return finish(
  documentStatus === "partial" ? "partial" : "extracted",
  cleanedStatements,
  data.rejection_reason ?? null
);

// =======================================================
// FINANCIAL DOCUMENT DATA ACCUMULATOR
// Mode: Run Once for All Items
// Input: Loop Over Items -> Done output
// Output: One combined financial dataset
// =======================================================

// 1. GET ALL COMPLETED LOOP RESULTS

const inputs = $input.all();

const TARGET_TYPES = [
  "balance_sheet",
  "income_statement",
  "cash_flow_statement"
];

const ALL_TYPES = [
  ...TARGET_TYPES,
  "other_financial_statement"
];

// 2. INITIALIZE COLLECTIONS

const documents = [];
const rejectedDocuments = [];
const reviewDocuments = [];

const groupedStatements = {
  balance_sheet: [],
  income_statement: [],
  cash_flow_statement: [],
  other_financial_statement: []
};

const companies = new Set();
const currencies = new Set();
const reportingPeriods = new Set();

const warnings = [];
const errors = [];

let totalAccounts = 0;
let totalStatements = 0;
let totalPeriods = 0;

let documentCounter = 0;

// Helper functions

function unique(values) {
  return [...new Set(values)];
}

function normalizeName(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/[^a-z0-9]/g, "");
}

function hasFinancialValues(statement) {
  if (!Array.isArray(statement.line_items)) {
    return false;
  }

  return statement.line_items.some(item =>
    item &&
    item.values &&
    typeof item.values === "object" &&
    Object.values(item.values).some(value =>
      typeof value === "number" &&
      Number.isFinite(value)
    )
  );
}

// Create a stable comparison signature
// for exact duplicate financial statements

function statementSignature(statement) {
  const normalizedItems = (statement.line_items || [])
    .map(item => ({
      key: item.key,
      values: Object.entries(item.values || {})
        .sort(([a], [b]) => a.localeCompare(b))
    }))
    .sort((a, b) =>
      String(a.key).localeCompare(String(b.key))
    );

  return JSON.stringify({
    company: normalizeName(statement.company),
    statement_type: statement.statement_type,
    currency: statement.currency ?? null,
    unit_multiplier: statement.unit_multiplier ?? null,
    periods: (statement.periods || [])
      .map(p => ({
        period_id: p.period_id,
        period_type: p.period_type,
        start_date: p.start_date,
        end_date: p.end_date
      }))
      .sort((a, b) =>
        String(a.period_id).localeCompare(String(b.period_id))
      ),
    line_items: normalizedItems
  });
}

const seenSignatures = new Map();
const duplicateStatements = [];

// =======================================================
// 3. PROCESS EVERY EXTRACTED DOCUMENT
// =======================================================

for (const inputItem of inputs) {

  // Normally each loop iteration returns one JSON object.
  // Also handle a nested array or { data: [...] }.

  const root = inputItem.json;

  const results = Array.isArray(root)
    ? root
    : Array.isArray(root.data)
      ? root.data
      : [root];

  for (const result of results) {

    documentCounter++;

    const documentID =
      `DOC_${String(documentCounter).padStart(4, "0")}`;

    const statements = Array.isArray(result.statements)
      ? result.statements
      : [];

    const documentWarnings = Array.isArray(result.warnings)
      ? result.warnings.map(String)
      : [];

    const documentErrors = Array.isArray(result.errors)
      ? result.errors.map(String)
      : [];

    const document = {
      documentID,

      filename:
        result.filename ??
        result.fileName ??
        result.sourceFilename ??
        null,

      fileIndex: result.fileIndex ?? null,

      originalDocumentType:
        result.documentType ?? null,

      extractionMethod:
        result.extractionMethod ?? null,

      company: result.company ?? null,

      documentStatus:
        result.documentStatus ?? "unknown",

      extractionStatus:
        result.extractionStatus ?? "unknown",

      extractionSuccessful:
        result.extractionSuccessful === true,

      detectedStatementTypes:
        Array.isArray(result.detectedStatementTypes)
          ? result.detectedStatementTypes
          : [],

      statements: [],

      validations:
        Array.isArray(result.validations)
          ? result.validations
          : [],

      warnings: documentWarnings,
      errors: documentErrors,

      rejectionReason:
        result.rejectionReason ?? null
    };

    // ---------------------------------------------------
    // 4. PROCESS EACH STATEMENT INSIDE THE DOCUMENT
    // ---------------------------------------------------

    for (let statementIndex = 0;
         statementIndex < statements.length;
         statementIndex++) {

      const statement = statements[statementIndex];

      if (!statement ||
          !ALL_TYPES.includes(statement.statement_type)) {
        document.warnings.push(
          `Unknown or invalid statement at index ${statementIndex}.`
        );
        continue;
      }

      const periods = Array.isArray(statement.periods)
        ? statement.periods
        : [];

      const lineItems = Array.isArray(statement.line_items)
        ? statement.line_items
        : [];

      if (
        periods.length === 0 ||
        lineItems.length === 0 ||
        !hasFinancialValues(statement)
      ) {
        document.warnings.push(
          `${statement.statement_type} at index ` +
          `${statementIndex} has no usable financial values.`
        );
        continue;
      }

      const cleanStatement = {
        statementID:
          `${documentID}_STMT_${statementIndex + 1}`,

        sourceDocumentID: documentID,

        filename: document.filename,

        statement_type: statement.statement_type,

        company:
          statement.company ??
          document.company ??
          null,

        currency:
          statement.currency ?? null,

        unit_multiplier:
          statement.unit_multiplier ?? null,

        periods,
        line_items: lineItems,

        warnings: Array.isArray(statement.warnings)
          ? statement.warnings
          : []
      };

      // Track exact duplicate statements

      const signature = statementSignature(cleanStatement);

      if (seenSignatures.has(signature)) {
        const originalID = seenSignatures.get(signature);

        duplicateStatements.push({
          statementID: cleanStatement.statementID,
          originalStatementID: originalID,
          sourceDocumentID: documentID,
          statement_type: cleanStatement.statement_type
        });

        cleanStatement.possibleDuplicateOf = originalID;

        document.warnings.push(
          `Possible duplicate ${cleanStatement.statement_type}: ` +
          `${originalID}`
        );
      } else {
        seenSignatures.set(
          signature,
          cleanStatement.statementID
        );

        cleanStatement.possibleDuplicateOf = null;
      }

      // Store in the original document

      document.statements.push(cleanStatement);

      // Also organize by financial statement type

      groupedStatements[
        cleanStatement.statement_type
      ].push(cleanStatement);

      // Collect reporting metadata

      if (cleanStatement.company) {
        companies.add(cleanStatement.company);
      }

      if (cleanStatement.currency) {
        currencies.add(cleanStatement.currency);
      }

      for (const period of periods) {
        reportingPeriods.add(
          JSON.stringify({
            period_type: period.period_type ?? null,
            start_date: period.start_date ?? null,
            end_date: period.end_date ?? null,
            label: period.label ?? null
          })
        );
      }

      totalStatements++;
      totalAccounts += lineItems.length;
      totalPeriods += periods.length;
    }

    // ---------------------------------------------------
    // 5. CLASSIFY DOCUMENT RESULTS
    // ---------------------------------------------------

    if (document.statements.length === 0) {
      rejectedDocuments.push(document);

      if (documentErrors.length > 0) {
        errors.push(
          `${documentID}: ${documentErrors.join("; ")}`
        );
      }

      continue;
    }

    documents.push(document);

    if (
      !document.extractionSuccessful ||
      document.extractionStatus !== "ready" ||
      document.warnings.length > 0 ||
      document.errors.length > 0
    ) {
      reviewDocuments.push(documentID);
    }
  }
}

// =======================================================
// 6. CROSS-DOCUMENT VALIDATION
// =======================================================

if (companies.size > 1) {

  const normalizedCompanies = unique(
    [...companies].map(normalizeName)
  );

  if (normalizedCompanies.length > 1) {
    warnings.push(
      "Multiple company identities detected. " +
      "Do not merge unrelated company financial data."
    );
  }
}

if (currencies.size > 1) {
  warnings.push(
    "Multiple currencies detected. " +
    "Currency normalization is required before combining."
  );
}

if (duplicateStatements.length > 0) {
  warnings.push(
    `${duplicateStatements.length} possible duplicate ` +
    `financial statements detected.`
  );
}

if (reviewDocuments.length > 0) {
  warnings.push(
    `${reviewDocuments.length} document(s) require review.`
  );
}

if (documents.length === 0) {
  errors.push(
    "No usable financial documents were collected."
  );
}

// Check different reporting multipliers

const multipliers = unique(
  Object.values(groupedStatements)
    .flat()
    .map(s => s.unit_multiplier)
    .filter(x => x !== null && x !== undefined)
);

if (multipliers.length > 1) {
  warnings.push(
    "Different financial reporting unit multipliers detected."
  );
}

// =======================================================
// 7. FINANCIAL STATEMENT COVERAGE
// =======================================================

const coverage = {
  balanceSheet:
    groupedStatements.balance_sheet.length > 0,

  incomeStatement:
    groupedStatements.income_statement.length > 0,

  cashFlowStatement:
    groupedStatements.cash_flow_statement.length > 0
};

// =======================================================
// 8. FINAL DATASET STATUS
// =======================================================

let datasetStatus = "collected";

if (documents.length === 0) {
  datasetStatus = "no_usable_data";
} else if (
  warnings.length > 0 ||
  errors.length > 0 ||
  reviewDocuments.length > 0
) {
  datasetStatus = "review_required";
}

// =======================================================
// 9. RETURN ONE FINANCIAL DATASET
// =======================================================

return [
  {
    json: {
      datasetStatus,

      readyForConsolidation:
        datasetStatus === "collected",

      companies: [...companies],
      currencies: [...currencies],

      statementCoverage: coverage,

      reportingPeriods:
        [...reportingPeriods].map(JSON.parse),

      summary: {
        totalInputItems: inputs.length,

        totalDocumentsProcessed: documentCounter,

        documentsCollected: documents.length,
        documentsRejected: rejectedDocuments.length,

        documentsNeedingReview: reviewDocuments.length,

        totalStatements,
        totalAccounts,
        totalPeriods,

        balanceSheets:
          groupedStatements.balance_sheet.length,

        incomeStatements:
          groupedStatements.income_statement.length,

        cashFlowStatements:
          groupedStatements.cash_flow_statement.length,

        supplementaryStatements:
          groupedStatements.other_financial_statement.length,

        possibleDuplicateStatements:
          duplicateStatements.length
      },

      documents,
      rejectedDocuments,
      reviewDocuments,

      groupedStatements,

      duplicateStatements,

      warnings: unique(warnings),
      errors: unique(errors)
    }
  }
];
;

// CONSOLIDATE & VALIDATE FINANCIAL DATA
// n8n Code Node
// Mode: Run Once for All Items

const source = $input.first().json;

const groups = new Map();
const conflicts = [];
const warnings = [];
const checks = [];

const docs = Array.isArray(source.documents)
  ? source.documents
  : [];

const validTypes = [
  "balance_sheet",
  "income_statement",
  "cash_flow_statement",
  "other_financial_statement"
];

function normalize(s) {
  return String(s || "")
    .toLowerCase()
    .replace(/[^a-z0-9]/g, "");
}

function number(v) {
  return typeof v === "number" &&
    Number.isFinite(v);
}

// Map alternate source account keys to canonical keys.
// Keep originalKey for auditability.
// Never invent amounts or combine unrelated totals.

const ACCOUNT_KEY_ALIASES = {
  total_shareholders_equity: "total_equity",
  total_stockholders_equity: "total_equity",
  shareholders_equity: "total_equity",
  shareholder_equity: "total_equity",
  shareholders_equity_total: "total_equity",
  total_equity_attributable_to_shareholders:
    "total_equity",
  stockholders_equity: "total_equity",
  total_shareholder_equity: "total_equity",
  total_shareholders_equity_and_reserves:
    "total_equity",

  total_current_asset: "total_current_assets",
  current_assets_total: "total_current_assets",

  total_current_liability:
    "total_current_liabilities",
  current_liabilities_total:
    "total_current_liabilities",

  accounts_receivable_net: "accounts_receivable",
  trade_receivables: "accounts_receivable",

  prepaid_expense: "prepaid_expenses",
  inventories: "inventory"
};

function keyOf(raw) {
  const k = String(raw || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");

  return ACCOUNT_KEY_ALIASES[k] || k;
}

// Identify exact matches, small possible rounding
// differences, and material discrepancies.
// The original financial amounts are preserved.

function checkAmount(
  label,
  period,
  values,
  difference,
  group
) {
  const magnitude = Math.max(
    ...values.map(v => Math.abs(v))
  );

  const integerSource = values.every(
    Number.isInteger
  );

  const tolerance =
    integerSource && magnitude >= 1000
      ? 1
      : 0.01;

  const abs = Math.abs(difference);

  const status =
    abs < 0.000001
      ? "passed"
      : abs <= tolerance
        ? "rounding_difference"
        : "failed";

  checks.push({
    statementType: group.statementType,
    period,
    check: label,
    difference: Number(difference.toFixed(6)),
    tolerance,
    status
  });

  if (status !== "passed") {
    group.warnings.push(
      `${label} (${period}): difference ` +
      `${difference.toFixed(2)} in source units; ` +
      (
        status === "rounding_difference"
          ? "possible source rounding"
          : "requires review"
      ) +
      "."
    );
  }
}

function close(a, b) {
  return Math.abs(a - b) <=
    Math.max(
      0.01,
      Math.max(Math.abs(a), Math.abs(b)) * 0.000001
    );
}

// ============================================
// 1. CONVERT DOCUMENTS INTO PERIOD RECORDS
// ============================================

for (const doc of docs) {
  for (const stmt of doc.statements || []) {

    if (!validTypes.includes(stmt.statement_type)) {
      continue;
    }

    const company =
      stmt.company ||
      doc.company ||
      "Unknown";

    const scale = stmt.unit_multiplier;

    const validScale =
      [1, 1000, 1000000].includes(scale);

    for (const period of stmt.periods || []) {

      const periodID = period.period_id;
      const endDate = period.end_date || null;
      const startDate = period.start_date || null;

      const periodType =
        period.period_type || "unknown";

      // Avoid merging incompatible periods,
      // currencies or reporting units.

      const groupKey = JSON.stringify([
        normalize(company),
        stmt.statement_type,
        startDate,
        endDate,
        periodType,
        stmt.currency ?? null,
        scale ?? null
      ]);

      if (!groups.has(groupKey)) {
        groups.set(groupKey, {
          company,
          statementType: stmt.statement_type,
          currency: stmt.currency ?? null,
          unitMultiplier: scale ?? null,

          reportingPeriod: {
            startDate,
            endDate,
            periodType,
            label: period.label || periodID
          },

          accounts: {},
          sources: [],
          warnings: []
        });
      }

      const group = groups.get(groupKey);

      group.sources.push({
        documentID: doc.documentID,
        statementID: stmt.statementID,
        filename: doc.filename ?? null,
        originalPeriodID: periodID
      });

      for (const item of stmt.line_items || []) {

        const raw = item.values?.[periodID];

        if (!number(raw)) {
          continue;
        }

        const originalKey =
          String(item.key || "").trim();

        const key = keyOf(originalKey);

        if (!key) continue;

        const proposed = {
          key,
          originalKey,
          label: item.label || originalKey,
          section: item.section || null,
          subsection: item.subsection || null,
          reportedValue: raw,

          normalizedValue: validScale
            ? raw * scale
            : null,

          sourceDocumentID: doc.documentID,
          sourceStatementID: stmt.statementID,
          sourcePage: item.source_page ?? null
        };

        if (group.accounts[key]) {

          const existing =
            group.accounts[key];

          if (!close(existing.reportedValue, raw)) {

            conflicts.push({
              company,
              statementType: stmt.statement_type,
              period: endDate,
              account: key,
              existingValue: existing.reportedValue,
              conflictingValue: raw,

              sources: [
                existing.sourceStatementID,
                stmt.statementID
              ]
            });
          }

          // Never sum duplicate source accounts.
          continue;
        }

        group.accounts[key] = proposed;
      }
    }
  }
}

// ============================================
// 2. VALIDATE CONSOLIDATED STATEMENTS
// ============================================

const consolidatedStatements = [
  ...groups.values()
];

for (const group of consolidatedStatements) {

  const accounts = group.accounts;

  function value(key) {
    return accounts[key]?.reportedValue ?? null;
  }

  if (group.statementType === "balance_sheet") {

    const assets = value("total_assets");
    const liabilities = value("total_liabilities");
    const equity = value("total_equity");

    const period =
      group.reportingPeriod.endDate;

    // Assets = Liabilities + Equity

    if (
      [assets, liabilities, equity].every(number)
    ) {

      checkAmount(
        "accounting_equation",
        period,
        [assets, liabilities, equity],
        assets - liabilities - equity,
        group
      );

    } else {

      checks.push({
        statementType: "balance_sheet",
        period,
        check: "accounting_equation",
        status: "missing_data",

        missingKeys: [
          "total_assets",
          "total_liabilities",
          "total_equity"
        ].filter(k => !number(value(k)))
      });

      group.warnings.push(
        "Accounting equation cannot be checked " +
        `for ${period}: major total missing or ` +
        "named differently."
      );
    }

    // ----------------------------------------
    // Current assets subtotal validation
    // ----------------------------------------

    const subtotal =
      value("total_current_assets");

    const pieces = [
      "cash",
      "accounts_receivable",
      "prepaid_expenses",
      "inventory"
    ];

    // Only test when this exact recognized
    // group of accounts is available.

    if (
      number(subtotal) &&
      pieces.every(k => number(value(k)))
    ) {

      const sum = pieces.reduce(
        (n, k) => n + value(k),
        0
      );

      checkAmount(
        "current_assets_subtotal",
        period,
        [
          subtotal,
          ...pieces.map(value)
        ],
        subtotal - sum,
        group
      );
    }
  }

  // ==========================================
  // CASH FLOW CLASSIFICATION
  // ==========================================

  if (
    group.statementType === "cash_flow_statement"
  ) {

    const isFundsFlow =
      number(value("total_sources_of_funds")) ||
      number(value("total_uses_of_funds"));

    group.cashFlowClassification = isFundsFlow
      ? "sources_and_uses_of_funds"
      : "cash_flow_statement";

    if (isFundsFlow) {
      group.warnings.push(
        "Sources-and-uses statement: do not " +
        "assume standard operating cash flow " +
        "is available."
      );
    }

    const opening =
      value("cash_beginning_of_period");

    const change =
      value("net_cash_flow_period");

    const closing =
      value("cash_end_of_period");

    if (
      [opening, change, closing].every(number)
    ) {

      const difference =
        opening + change - closing;

      checks.push({
        statementType: "cash_flow_statement",
        period: group.reportingPeriod.endDate,
        check: "cash_reconciliation",
        difference,

        status: close(difference, 0)
          ? "passed"
          : "failed"
      });

      if (!close(difference, 0)) {
        group.warnings.push(
          "Opening cash plus cash movement " +
          "does not equal closing cash."
        );
      }
    }
  }

  group.accountCount =
    Object.keys(accounts).length;

  if (group.unitMultiplier === null) {
    group.warnings.push(
      "Reporting unit multiplier unknown."
    );
  }
}

// ============================================
// 3. CROSS-DOCUMENT CHECKS
// ============================================

const companyNames = [
  ...new Set(
    consolidatedStatements.map(
      s => normalize(s.company)
    )
  )
];

if (companyNames.length > 1) {
  warnings.push(
    "Multiple companies found. " +
    "Keep their analysis separate."
  );
}

if (conflicts.length) {
  warnings.push(
    `${conflicts.length} conflicting ` +
    "account values detected."
  );
}

const periodGroups = new Map();

for (const s of consolidatedStatements) {

  const key = JSON.stringify([
    normalize(s.company),
    s.statementType,
    s.reportingPeriod.startDate,
    s.reportingPeriod.endDate,
    s.reportingPeriod.periodType
  ]);

  if (!periodGroups.has(key)) {
    periodGroups.set(key, []);
  }

  periodGroups.get(key).push(s);
}

let incompatibleGroups = 0;

for (const items of periodGroups.values()) {

  if (items.length > 1) {
    incompatibleGroups++;

    warnings.push(
      "Statements with matching periods " +
      "but different currencies or reporting " +
      "units require review."
    );
  }
}

const failedChecks = checks.filter(
  c => c.status === "failed"
);

const allWarnings = [
  ...warnings,
  ...consolidatedStatements.flatMap(
    s => s.warnings
  )
];

// ============================================
// 4. RETURN FINANCIAL DATA
// ============================================

return [{
  json: {

    company: companyNames.length === 1
      ? consolidatedStatements[0]?.company
      : null,

    consolidationStatus:
      consolidatedStatements.length === 0
        ? "no_data"
        : conflicts.length ||
          failedChecks.length ||
          incompatibleGroups
          ? "review_required"
          : allWarnings.length
            ? "review_recommended"
            : "ready",

    canCalculate:
      consolidatedStatements.length > 0 &&
      conflicts.length === 0 &&
      failedChecks.length === 0 &&
      incompatibleGroups === 0 &&
      companyNames.length <= 1,

    statementCoverage:
      source.statementCoverage || {},

    summary: {
      inputDocuments: docs.length,
      consolidatedStatementPeriods:
        consolidatedStatements.length,
      conflicts: conflicts.length,
      failedChecks: failedChecks.length,
      incompatibleGroups
    },

    consolidatedStatements,
    validationChecks: checks,
    conflicts,

    warnings: [...new Set(allWarnings)],

    sourceDocuments: docs,

    rejectedDocuments:
      source.rejectedDocuments || []
  }
}];

// =======================================================
// CALCULATE FINANCIAL RATIOS & TRENDS
// n8n Code Node: Run Once for All Items
// No LLM required. All calculations are deterministic.
// =======================================================

const data = $input.first().json;
const statements = data.consolidatedStatements || [];

const warnings = [...(data.warnings || [])];
const metrics = [];
const trends = [];

const aliases = {
  currentAssets: ["total_current_assets"],
  currentLiabilities: ["total_current_liabilities"],
  totalAssets: ["total_assets"],
  totalLiabilities: ["total_liabilities"],
  totalEquity: ["total_equity", "stockholders_equity",
    "shareholders_equity"],
  cash: ["cash_and_cash_equivalents",
    "cash_and_bank_current_accounts",
    "cash_and_bank", "cash"],
  revenue: ["total_revenue", "total_revenues", "sales_revenue",
    "net_revenue", "net_sales", "total_income", "revenues",
    "total_financial_income", "total_operating_revenue"],
  grossProfit: ["gross_profit", "gross_income"],
  operatingIncome: ["operating_income", "operating_profit",
    "ebit", "net_income_from_operations"],
  netIncome: ["net_income", "net_profit",
    "net_earnings", "net_income_loss", "net_profit_loss",
    "excess_of_income_over_expenses",
    "excess_income_over_expenses",
    "excess_of_revenue_over_expenses",
    "net_surplus", "net_surplus_deficit",
    "surplus_for_the_year", "profit_for_the_year"],
  grossLoans: ["loans_outstanding_gross", "gross_loans",
    "gross_loans_outstanding"],
  pastDueLoans: ["loans_outstanding_past_due", "past_due_loans",
    "nonperforming_loans"],
  loanLossReserve: ["loan_loss_reserve", "loan_loss_allowance",
    "allowance_for_loan_losses"],
  operatingCashFlow: ["net_cash_from_operating_activities",
    "net_cash_provided_by_operating_activities",
    "operating_cash_flow", "cash_flow_from_operations"],
  netCashChange: ["net_change_in_cash",
    "net_cash_flow_period",
    "net_increase_in_cash_and_cash_equivalents"],
  openingCash: ["cash_beginning_of_period"],
  closingCash: ["cash_end_of_period"]
};

function finite(v) {
  return typeof v === "number" && Number.isFinite(v);
}

function safeDivide(a, b) {
  if (!finite(a) || !finite(b) || b === 0) return null;
  const result = a / b;
  return Number.isFinite(result) ? result : null;
}

function round(v, digits = 6) {
  if (!finite(v)) return null;
  return Number(v.toFixed(digits));
}

function amount(statement, metric) {
  const accounts = statement.accounts || {};
  for (const key of aliases[metric] || []) {
    const v = accounts[key]?.reportedValue;
    if (finite(v)) return v;
  }
  return null;
}

function addMetric(record, key, value, unit, description) {
  record.metrics[key] = {
    value: round(value),
    unit,
    description,
    available: finite(value)
  };
}

const companyNames = [
  ...new Set(statements.map(s =>
    String(s.company || "").toLowerCase()
      .replace(/[^a-z0-9]/g, "")
  ))
];

// Do not calculate across unrelated companies or
// datasets with known validation conflicts.
if (
  data.canCalculate === false ||
  companyNames.length > 1 ||
  (data.conflicts || []).length > 0 ||
  (data.validationChecks || []).some(
    x => x.status === "failed"
  )
) {
  return [{
    json: {
      calculationStatus: "blocked",
      company: data.company ?? null,
      metrics: [],
      trends: [],
      warnings,
      errors: [
        "Consolidation requires review before calculation."
      ]
    }
  }];
}

// =======================================================
// 1. CALCULATE EACH STATEMENT'S RATIOS
// =======================================================

for (const statement of statements) {

  const type = statement.statementType;
  const date = statement.reportingPeriod?.endDate ?? null;

  const record = {
    company: statement.company,
    statementType: type,
    period: date,
    periodType:
      statement.reportingPeriod?.periodType ?? "unknown",
    currency: statement.currency ?? null,
    unitMultiplier: statement.unitMultiplier ?? null,
    metrics: {}
  };

  // -------------------------------
  // BALANCE SHEET
  // -------------------------------

  if (type === "balance_sheet") {

    const currentAssets = amount(statement, "currentAssets");
    const currentLiabilities =
      amount(statement, "currentLiabilities");
    const totalAssets = amount(statement, "totalAssets");
    const totalLiabilities =
      amount(statement, "totalLiabilities");
    const totalEquity = amount(statement, "totalEquity");
    const cash = amount(statement, "cash");

    addMetric(record, "current_ratio",
      safeDivide(currentAssets, currentLiabilities),
      "ratio", "Current assets / current liabilities");

    addMetric(record, "cash_ratio",
      safeDivide(cash, currentLiabilities),
      "ratio", "Cash / current liabilities");

    addMetric(record, "working_capital",
      finite(currentAssets) && finite(currentLiabilities)
        ? currentAssets - currentLiabilities : null,
      "reported_amount", "Current assets - current liabilities");

    addMetric(record, "liabilities_to_assets",
      safeDivide(totalLiabilities, totalAssets),
      "ratio", "Total liabilities / total assets");

    addMetric(record, "equity_to_assets",
      safeDivide(totalEquity, totalAssets),
      "ratio", "Total equity / total assets");

    addMetric(record, "liabilities_to_equity",
      safeDivide(totalLiabilities, totalEquity),
      "ratio", "Total liabilities / total equity");

    addMetric(record, "total_assets", totalAssets,
      "reported_amount", "Reported total assets");

    addMetric(record, "total_liabilities", totalLiabilities,
      "reported_amount", "Reported total liabilities");

    addMetric(record, "total_equity", totalEquity,
      "reported_amount", "Reported total equity");

    // Lending metrics: only added when the statement has a loan book.
    const grossLoans = amount(statement, "grossLoans");
    if (finite(grossLoans)) {
      const pastDue = amount(statement, "pastDueLoans");
      const reserveRaw = amount(statement, "loanLossReserve");
      const reserve = finite(reserveRaw) ? Math.abs(reserveRaw) : null;

      addMetric(record, "past_due_loans_to_gross_loans",
        safeDivide(pastDue, grossLoans),
        "decimal", "Past-due loans / gross loans");

      addMetric(record, "loan_loss_reserves_to_past_due_loans",
        safeDivide(reserve, pastDue),
        "decimal", "Loan-loss reserve / past-due loans");

      addMetric(record, "loan_loss_reserves_to_gross_loans",
        safeDivide(reserve, grossLoans),
        "decimal", "Loan-loss reserve / gross loans");
    }
  }

  // -------------------------------
  // INCOME STATEMENT
  // -------------------------------

  if (type === "income_statement") {

    const revenue = amount(statement, "revenue");
    const grossProfit = amount(statement, "grossProfit");
    const operatingIncome =
      amount(statement, "operatingIncome");
    const netIncome = amount(statement, "netIncome");

    addMetric(record, "revenue", revenue,
      "reported_amount", "Reported revenue or financial income");

    addMetric(record, "gross_profit", grossProfit,
      "reported_amount", "Reported gross profit");

    addMetric(record, "operating_income", operatingIncome,
      "reported_amount", "Reported operating income");

    addMetric(record, "net_income", netIncome,
      "reported_amount", "Reported net income");

    addMetric(record, "gross_margin",
      safeDivide(grossProfit, revenue),
      "decimal", "Gross profit / revenue");

    addMetric(record, "operating_margin",
      safeDivide(operatingIncome, revenue),
      "decimal", "Operating income / revenue");

    addMetric(record, "net_margin",
      safeDivide(netIncome, revenue),
      "decimal", "Net income / revenue");
  }

  // -------------------------------
  // CASH FLOW STATEMENT
  // -------------------------------

  if (type === "cash_flow_statement") {

    const isFundsFlow =
      statement.cashFlowClassification ===
      "sources_and_uses_of_funds";

    // Do not turn sources-and-uses amounts
    // into standard operating cash flow.

    const operatingCashFlow = isFundsFlow
      ? null
      : amount(statement, "operatingCashFlow");

    const netCashChange =
      amount(statement, "netCashChange");

    const openingCash = amount(statement, "openingCash");
    const closingCash = amount(statement, "closingCash");

    record.cashFlowClassification =
      statement.cashFlowClassification ?? "unknown";

    addMetric(record, "operating_cash_flow",
      operatingCashFlow,
      "reported_amount", "Operating cash flow");

    addMetric(record, "net_cash_change",
      netCashChange,
      "reported_amount", "Net change in cash");

    addMetric(record, "opening_cash",
      openingCash,
      "reported_amount", "Opening cash");

    addMetric(record, "closing_cash",
      closingCash,
      "reported_amount", "Closing cash");

    if (isFundsFlow) {
      warnings.push(
        `${date}: sources-and-uses statement; ` +
        "standard operating cash flow is unavailable."
      );
    }
  }

  metrics.push(record);
}

// =======================================================
// 1b. CROSS-STATEMENT RETURNS (income statement + balance sheet)
// =======================================================

for (const inc of metrics.filter(x =>
      x.statementType === "income_statement" && x.period)) {

  const bsRec = metrics.find(x =>
    x.statementType === "balance_sheet" &&
    x.period === inc.period &&
    x.currency === inc.currency &&
    x.unitMultiplier === inc.unitMultiplier);

  const netIncome = inc.metrics.net_income?.value;
  if (!bsRec || !finite(netIncome)) continue;

  const record = {
    company: inc.company,
    statementType: "combined",
    period: inc.period,
    periodType: inc.periodType,
    currency: inc.currency,
    unitMultiplier: inc.unitMultiplier,
    metrics: {}
  };

  addMetric(record, "return_on_assets",
    safeDivide(netIncome, bsRec.metrics.total_assets?.value),
    "decimal", "Net income / year-end total assets");

  addMetric(record, "return_on_equity",
    safeDivide(netIncome, bsRec.metrics.total_equity?.value),
    "decimal", "Net income / year-end total equity");

  metrics.push(record);
}

// =======================================================
// 2. YEAR-OVER-YEAR TRENDS
// =======================================================

// Comparisons must have matching statement types,
// reporting periods, currencies and unit scales.

const types = [
  "balance_sheet",
  "income_statement",
  "cash_flow_statement",
  "combined"
];

for (const type of types) {

  const records = metrics
    .filter(x => x.statementType === type && x.period)
    .sort((a, b) => a.period.localeCompare(b.period));

  for (let i = 1; i < records.length; i++) {

    const previous = records[i - 1];
    const current = records[i];

    const sameUnits =
      previous.currency === current.currency &&
      previous.unitMultiplier === current.unitMultiplier;

    const samePeriodType =
      previous.periodType === current.periodType;

    const yearsApart =
      Number(current.period.slice(0, 4)) -
      Number(previous.period.slice(0, 4));

    // Annual balance sheet or annual income comparisons.
    const eligible =
      sameUnits &&
      samePeriodType &&
      yearsApart === 1 &&
      current.period.slice(5) === previous.period.slice(5) &&
      (type === "balance_sheet" ||
        current.periodType === "full_year");

    if (!eligible) continue;

    const changes = {};

    for (const [key, currentMetric] of
         Object.entries(current.metrics)) {

      const oldMetric = previous.metrics[key];

      if (
        !oldMetric ||
        !finite(currentMetric.value) ||
        !finite(oldMetric.value)
      ) continue;

      const difference =
        currentMetric.value - oldMetric.value;

      // Percentage growth is not meaningful when
      // the previous value is zero or negative.
      const growth =
        oldMetric.value > 0 &&
        currentMetric.value >= 0
          ? safeDivide(difference, oldMetric.value)
          : null;

      changes[key] = {
        previous: oldMetric.value,
        current: currentMetric.value,
        absoluteChange: round(difference),
        growthRate: round(growth),
        unit: currentMetric.unit
      };
    }

    trends.push({
      statementType: type,
      fromPeriod: previous.period,
      toPeriod: current.period,
      changes
    });
  }
}

// =======================================================
// 3. DATA COVERAGE SUMMARY
// =======================================================

const availableTypes = [
  ...new Set(metrics.map(x => x.statementType))
];

const availableMetricCount = metrics.reduce(
  (sum, record) =>
    sum + Object.values(record.metrics)
      .filter(m => m.available).length,
  0
);

const missingMetricCount = metrics.reduce(
  (sum, record) =>
    sum + Object.values(record.metrics)
      .filter(m => !m.available).length,
  0
);

// =======================================================
// 4. RETURN ANALYSIS-READY DATA
// =======================================================

return [{
  json: {
    company: data.company ?? null,

    calculationStatus:
      availableMetricCount > 0
        ? "calculated"
        : "insufficient_data",

    industryClassification: "unclassified",

    statementCoverage: data.statementCoverage ?? {},

    summary: {
      statementPeriodsAnalyzed: metrics.length,
      availableMetricCount,
      missingMetricCount,
      trendComparisons: trends.length,
      statementTypes: availableTypes
    },

    financialMetrics: metrics,
    financialTrends: trends,

    validationChecks: data.validationChecks ?? [],
    warnings: [...new Set(warnings)],

    // Keep these for the scoring and Excel stages.
    consolidatedStatements: statements
  }
}];

const input = $input.first().json;

const records = Array.isArray(input.financialMetrics)
  ? input.financialMetrics : [];

const statements = Array.isArray(input.consolidatedStatements)
  ? input.consolidatedStatements : [];

const warnings = [...(input.warnings || [])];
const errors = [];

// ============================================
// HELPERS
// ============================================

function num(v) {
  return typeof v === "number" && Number.isFinite(v)
    ? v : null;
}

function round(v, d = 2) {
  return num(v) === null ? null : Number(v.toFixed(d));
}

function clamp(x) {
  return Math.max(0, Math.min(100, x));
}

function up(value, bad, good) {
  return num(value) === null
    ? null
    : clamp(100 * (value - bad) / (good - bad));
}

function down(value, good, bad) {
  return num(value) === null
    ? null
    : clamp(100 * (bad - value) / (bad - good));
}

function ratio(a, b) {
  return num(a) === null || num(b) === null || b === 0
    ? null : a / b;
}

function metric(r, name) {
  return num(r?.metrics?.[name]?.value);
}

function latest(type) {
  return records
    .filter(r => r.statementType === type && r.period)
    .sort((a, b) => b.period.localeCompare(a.period))[0] || null;
}

function statement(type, date) {
  return statements.find(s =>
    s.statementType === type &&
    s.reportingPeriod?.endDate === date
  ) || null;
}

function account(s, names) {
  for (const key of names) {
    const x = num(s?.accounts?.[key]?.reportedValue);
    if (x !== null) return x;
  }
  return null;
}

function getTrend(type, name, toPeriod) {
  const t = (input.financialTrends || []).find(x =>
    x.statementType === type &&
    x.toPeriod === toPeriod
  );

  return num(t?.changes?.[name]?.growthRate);
}

// ============================================
// CHECK WHETHER CALCULATIONS ARE AVAILABLE
// ============================================

if (input.calculationStatus !== "calculated") {
  return [{
    json: {
      company: input.company ?? null,
      scoringStatus: "blocked",
      profile: null,
      financialHealthScore: null,
      dataCoveragePercent: 0,
      scoreModel: "No valid financial metrics",
      latestPeriods: {
        balanceSheet: null,
        incomeStatement: null,
        cashFlowStatement: null
      },
      scoreCategories: [],
      warnings,
      errors: [
        "Financial calculations are unavailable. No score generated."
      ],
      financialMetrics: records,
      financialTrends: input.financialTrends || [],
      validationChecks: input.validationChecks || [],
      consolidatedStatements: statements
    }
  }];
}

// ============================================
// IDENTIFY LATEST STATEMENTS AND INDUSTRY
// ============================================

const bs = latest("balance_sheet");
const inc = latest("income_statement");
const cf = latest("cash_flow_statement");

const bsSource = bs
  ? statement("balance_sheet", bs.period)
  : null;

const loanKeys = bsSource
  ? Object.keys(bsSource.accounts || {})
  : [];

const isLender =
  loanKeys.some(k => k.includes("loans_outstanding")) &&
  loanKeys.some(k =>
    k.includes("loan_loss_reserve") ||
    k.includes("loan_loss_allowance")
  );

const profile = isLender
  ? "lending_prototype"
  : "general_business_prototype";

// ============================================
// CATEGORY SCORING
// ============================================

// Category weights are percentages.
// Missing components do not receive zero points.
// Instead, their weights reduce data coverage.

const categories = [];

function addCategory(name, weight, parts) {

  const available = parts.filter(
    p => num(p.score) !== null
  );

  const totalPartWeight = parts.reduce(
    (s, p) => s + p.weight, 0
  );

  const availablePartWeight = available.reduce(
    (s, p) => s + p.weight, 0
  );

  const categoryScore = availablePartWeight > 0
    ? available.reduce(
        (s, p) => s + p.score * p.weight, 0
      ) / availablePartWeight
    : null;

  const coverageShare = totalPartWeight
    ? availablePartWeight / totalPartWeight
    : 0;

  categories.push({
    name,
    baseWeight: weight,
    effectiveWeight: round(weight * coverageShare, 4),
    score: round(categoryScore),

    availability:
      availablePartWeight === 0
        ? "unavailable"
        : coverageShare < 0.999
          ? "partial"
          : "complete",

    components: parts.map(p => ({
      name: p.name,
      metricKey: p.metricKey || null,
      value: round(p.value, 6),
      weight: p.weight,
      score: round(p.score),
      available: num(p.score) !== null,
      // Thresholds that produced the score (illustrative prototype settings)
      direction: p.direction || null,   // "higher" or "lower" is better
      goal: p.goal ?? null,             // value that earns 100
      worry: p.worry ?? null,           // value that earns 0
      note: p.note || null
    }))
  });
}

// higher-is-better: 0 points at `worry`, 100 points at `goal`
function higher(name, metricKey, value, weight, worry, goal, note) {
  return {
    name, metricKey, value, weight, note,
    direction: "higher", worry, goal,
    score: up(value, worry, goal)
  };
}

// lower-is-better: 100 points at `goal`, 0 points at `worry`
function lower(name, metricKey, value, weight, goal, worry, note) {
  return {
    name, metricKey, value, weight, note,
    direction: "lower", worry, goal,
    score: down(value, goal, worry)
  };
}

// 100 = Strong ... 0 = At risk (presentation labels only)
function ratingFor(score) {
  if (num(score) === null) return null;
  if (score >= 80) return "Strong";
  if (score >= 65) return "Healthy";
  if (score >= 50) return "Fair";
  if (score >= 35) return "Weak";
  return "At risk";
}

// ============================================
// SHARED PROFITABILITY AND CASH FLOW METRICS
// ============================================

const revenue = metric(inc, "revenue");
const opMargin = metric(inc, "operating_margin");
const netMargin = metric(inc, "net_margin");

const revenueGrowth = inc
  ? getTrend("income_statement", "revenue", inc.period)
  : null;

const operatingCF = metric(cf, "operating_cash_flow");

// Do not confuse net change in cash with
// cash flow from operating activities.

const sameCashRevenuePeriod =
  cf && inc &&
  cf.period === inc.period &&
  cf.periodType === inc.periodType &&
  cf.currency === inc.currency &&
  cf.unitMultiplier === inc.unitMultiplier;

const ocfMargin = sameCashRevenuePeriod
  ? ratio(operatingCF, revenue)
  : null;

const cashOpening = metric(cf, "opening_cash");

const ocfToOpeningCash = ratio(
  operatingCF,
  cashOpening
);

const cashParts = [
  higher("Operating cash flow / revenue", "operating_cash_flow_margin",
    ocfMargin, 0.5, -0.10, 0.20),

  higher("Operating cash flow / opening cash", "operating_cash_flow_to_opening_cash",
    ocfToOpeningCash, 0.5, -0.5, 1.0,
    "Secondary proxy, not a substitute for full cash flow analysis")
];

// ============================================
// LENDING BUSINESS SCORING MODEL
// ============================================

if (isLender) {

  const grossLoans = account(bsSource, [
    "loans_outstanding_gross",
    "gross_loans",
    "gross_loans_outstanding"
  ]);

  const pastDue = account(bsSource, [
    "loans_outstanding_past_due",
    "past_due_loans",
    "nonperforming_loans"
  ]);

  const reserve = account(bsSource, [
    "loan_loss_reserve",
    "loan_loss_allowance",
    "allowance_for_loan_losses"
  ]);

  const pastDueShare = ratio(pastDue, grossLoans);

  const reserveCoverage = ratio(
    reserve === null ? null : Math.abs(reserve),
    pastDue
  );

  const equityRatio = metric(bs, "equity_to_assets");

  // CAPITAL: 25%
  addCategory("Capital strength", 25, [
    higher("Equity / assets", "equity_to_assets",
      equityRatio, 1, 0.08, 0.35)
  ]);

  // LOAN QUALITY: 25%
  addCategory("Loan portfolio quality", 25, [
    lower("Past-due loans / gross loans", "past_due_loans_to_gross_loans",
      pastDueShare, 0.65, 0.05, 0.25),

    higher("Loan-loss reserves / past-due loans", "loan_loss_reserves_to_past_due_loans",
      reserveCoverage, 0.35, 0, 0.75)
  ]);

  // LIQUIDITY: 20%
  addCategory("Liquidity (simplified)", 20, [
    higher("Cash / current liabilities", "cash_ratio",
      metric(bs, "cash_ratio"), 1, 0.03, 0.5)
  ]);

  // EARNINGS: 25%
  addCategory("Earnings performance", 25, [
    higher("Operating margin", "operating_margin",
      opMargin, 0.45, -0.10, 0.15),

    higher("Net margin", "net_margin",
      netMargin, 0.35, -0.10, 0.12),

    higher("Revenue growth", "revenue_growth",
      revenueGrowth, 0.20, -0.10, 0.20)
  ]);

  // OPERATING CASH: 5%
  addCategory("Operating cash generation", 5, cashParts);

  warnings.push(
    "Lending-sector scoring is a prototype, not a " +
    "regulatory capital, CAMELS, or credit rating assessment."
  );

} else {

  // ==========================================
  // GENERAL BUSINESS SCORING MODEL
  // ==========================================

  // LIQUIDITY: 35%
  addCategory("Liquidity", 35, [
    higher("Current ratio", "current_ratio",
      metric(bs, "current_ratio"), 0.65, 0.75, 2.5),

    higher("Cash ratio", "cash_ratio",
      metric(bs, "cash_ratio"), 0.35, 0.05, 0.5)
  ]);

  // SOLVENCY: 25%
  addCategory("Solvency", 25, [
    lower("Liabilities / assets", "liabilities_to_assets",
      metric(bs, "liabilities_to_assets"), 1, 0.25, 0.85)
  ]);

  // PROFITABILITY: 25%
  addCategory("Profitability & growth", 25, [
    higher("Operating margin", "operating_margin",
      opMargin, 0.4, -0.10, 0.20),

    higher("Net margin", "net_margin",
      netMargin, 0.4, -0.10, 0.15),

    higher("Revenue growth", "revenue_growth",
      revenueGrowth, 0.2, -0.15, 0.25)
  ]);

  // OPERATING CASH: 15%
  addCategory("Operating cash generation", 15, cashParts);
}

// ============================================
// CALCULATE ADAPTIVE OVERALL SCORE
// ============================================

const effectiveTotal = categories.reduce(
  (s, c) => s + c.effectiveWeight, 0
);

const weightedSum = categories.reduce(
  (s, c) =>
    s + (c.score === null
      ? 0
      : c.score * c.effectiveWeight),
  0
);

const financialScore = effectiveTotal > 0
  ? round(weightedSum / effectiveTotal, 1)
  : null;

const coverage = round(effectiveTotal, 1);

const scoreModel = categories
  .filter(c => c.score !== null)
  .map(c => c.name)
  .join(" + ") || "No valid categories";

// ============================================
// FINAL VALIDATION
// ============================================

const checksFailed = (input.validationChecks || [])
  .some(x => x.status === "failed");

if (checksFailed) {
  errors.push(
    "Financial validation failed; score withheld."
  );
}

if (cf && operatingCF === null) {
  warnings.push(
    "Operating cash flow unavailable: cash movement " +
    "is displayed but not scored as operating cash flow."
  );
}

if (coverage < 100) {
  warnings.push(
    "Incomplete metric coverage. Scores with different " +
    "coverage or profiles are not directly comparable."
  );
}

if (bs && inc && bs.period !== inc.period) {
  warnings.push(
    "Latest balance sheet and income statement periods differ."
  );
}

const blocked = errors.length > 0;

const publishedScore = blocked
  ? null
  : financialScore;

const status = blocked
  ? "blocked"
  : publishedScore === null
    ? "insufficient_data"
    : coverage >= 99.9
      ? "comprehensive_provisional"
      : "partial_provisional";

// ============================================
// FINAL OUTPUT
// ============================================

return [{
  json: {
    company: input.company ?? null,

    scoringStatus: status,
    profile,

    financialHealthScore: publishedScore,
    scoreRating: ratingFor(publishedScore),
    dataCoveragePercent: coverage,

    scoreModel,

    latestPeriods: {
      balanceSheet: bs?.period ?? null,
      incomeStatement: inc?.period ?? null,
      cashFlowStatement: cf?.period ?? null
    },

    scoreCategories: categories,

    scoringMethod: {
      formula:
        "sum(categoryScore * effectiveWeight) / sum(effectiveWeight)",

      explanation:
        "Effective weight equals base category weight " +
        "multiplied by the proportion of available component " +
        "weights. Missing components are excluded, not zeroed.",

      benchmarkPolicy:
        "Illustrative thresholds. Calibrate by industry " +
        "and historical outcomes before external use.",

      ratingBands:
        "80-100 Strong, 65-79 Healthy, 50-64 Fair, " +
        "35-49 Weak, below 35 At risk (presentation labels).",

      modelVersion: "prototype_v1"
    },

    summary: {
      scoredCategories:
        categories.filter(c => c.score !== null).length,

      totalCategories: categories.length,
      coverage,
      profile,

      comparisonCaution:
        "Scores calculated under different profiles " +
        "or data coverage are not directly comparable."
    },

    warnings: [...new Set(warnings)],
    errors,

    // Preserve data for later Excel generation
    financialMetrics: records,
    financialTrends: input.financialTrends || [],
    validationChecks: input.validationChecks || [],
    consolidatedStatements: statements
  }
}];
;

// PREPARE FINANCIAL ANALYST INPUT (v3)
// Mode: Run Once for All Items
//
// The analyst model only ever sees PRE-FORMATTED numbers ("38.9%", "5.03x",
// "106,300"). Small local models copy whatever they are given, so giving
// them raw decimals like 0.388523 is what produced unreadable sentences.

const data = $input.first().json;

const PERCENT_KEYS = new Set([
  "equity_to_assets", "liabilities_to_assets", "debt_to_assets",
  "operating_margin", "net_margin", "gross_margin", "revenue_growth",
  "return_on_assets", "return_on_equity",
  "past_due_loans_to_gross_loans",
  "loan_loss_reserves_to_past_due_loans",
  "loan_loss_reserves_to_gross_loans"
]);
const MULTIPLE_KEYS = new Set([
  "current_ratio", "cash_ratio", "quick_ratio",
  "liabilities_to_equity", "debt_to_equity", "interest_coverage"
]);

const isNum = v => typeof v === "number" && Number.isFinite(v);

// Scoring components may have decimal proportions OR multiples.
// Never convert a current ratio or cash ratio to 2,841.7%.
function componentUnit(p) {
  const key = String(p.metricKey || "");
  return MULTIPLE_KEYS.has(key) ? "multiple" :
    PERCENT_KEYS.has(key) ? "decimal" : "reported_amount";
}

function kindOf(key, unit) {
  const k = String(key || "").toLowerCase();
  if (PERCENT_KEYS.has(k) || k.endsWith("_margin") ||
      k.endsWith("_growth") || ["decimal", "proportion", "fraction"].includes(unit)) return "percent";
  if (MULTIPLE_KEYS.has(k) || ["x", "multiple", "times"].includes(unit)) return "multiple";
  return "amount";
}

function show(key, unit, value) {
  if (!isNum(value)) return null;
  const kind = kindOf(key, unit);
  if (kind === "percent") return (value * 100).toFixed(1) + "%";
  if (kind === "multiple") return value.toFixed(2) + "x";
  return value.toLocaleString("en-US", { maximumFractionDigits: 2 });
}

function changeText(key, unit, now, before) {
  if (!isNum(now) || !isNum(before)) return null;
  const kind = kindOf(key, unit);
  if (kind === "percent") {
    const d = (now - before) * 100;
    return (d >= 0 ? "+" : "") + d.toFixed(1) + " percentage points";
  }
  if (kind === "multiple") {
    const d = now - before;
    return (d >= 0 ? "+" : "") + d.toFixed(2) + "x";
  }
  if (before > 0 && now >= 0) {
    const g = (now - before) / before * 100;
    return (g >= 0 ? "+" : "") + g.toFixed(1) + "%";
  }
  return "moved from " + show(key, unit, before) + " to " + show(key, unit, now);
}

// ---- metrics by (statement, key) -> {period: {display, unit}} ----
const metricMap = new Map();
for (const r of data.financialMetrics || []) {
  for (const [key, m] of Object.entries(r.metrics || {})) {
    if (!(m && m.available === true && isNum(m.value))) continue;
    const id = r.statementType + "|" + key;
    if (!metricMap.has(id)) metricMap.set(id, { key, statement: r.statementType, unit: m.unit, byPeriod: {} });
    metricMap.get(id).byPeriod[r.period] = m.value;
  }
}

const allPeriods = [...new Set((data.financialMetrics || []).map(r => r.period).filter(Boolean))]
  .sort().reverse();
const latestPeriod = allPeriods[0] || null;
const priorPeriod = allPeriods[1] || null;

const readableMetrics = [...metricMap.values()].map(m => ({
  measure: m.key,
  statement: m.statement,
  latest: show(m.key, m.unit, m.byPeriod[latestPeriod]),
  prior: priorPeriod ? show(m.key, m.unit, m.byPeriod[priorPeriod]) : null,
  change: priorPeriod
    ? changeText(m.key, m.unit, m.byPeriod[latestPeriod], m.byPeriod[priorPeriod])
    : null
})).filter(m => m.latest !== null);

const analystContext = {
  company: data.company ?? null,

  assessment: {
    status: data.scoringStatus,
    financialHealthScore: data.financialHealthScore,
    scoreRating: data.scoreRating ?? null,
    dataCoveragePercent: data.dataCoveragePercent,
    profile: data.profile,
    model: data.scoreModel,
    methodology: data.scoringMethod
  },

  reportingPeriods: { latest: latestPeriod, prior: priorPeriod, ...(data.latestPeriods || {}) },

  scoreCategories: (data.scoreCategories || []).map(c => ({
    name: c.name,
    score: c.score,
    weightPercent: c.effectiveWeight,
    availability: c.availability,
    components: (c.components || []).map(p => ({
      name: p.name,
      value: show(p.metricKey, componentUnit(p), p.value),
      score: p.score,
      available: p.available,
      goalValue: show(p.metricKey, componentUnit(p), p.goal),
      worryValue: show(p.metricKey, componentUnit(p), p.worry)
    }))
  })),

  // Every number below is already formatted. Quote them exactly.
  measures: readableMetrics,

  currencyNote: (() => {
    const first = (data.financialMetrics || [])[0] || {};
    return first.currency || first.unitMultiplier
      ? { currency: first.currency ?? null, unitMultiplier: first.unitMultiplier ?? null }
      : "Currency and scale are not stated in the source: say 'reported units', add no currency symbol.";
  })(),

  cashFlowNote: (data.financialMetrics || []).some(r => r.cashFlowClassification === "sources_and_uses_of_funds")
    ? "The cash statement is a sources-and-uses-of-funds statement, not an operating cash flow statement."
    : null,

  validationChecks: data.validationChecks || [],
  warnings: data.warnings || [],
  errors: data.errors || []
};

return [{
  json: {
    company: data.company,
    financialHealthScore: data.financialHealthScore,
    scoreRating: data.scoreRating ?? null,
    dataCoveragePercent: data.dataCoveragePercent,
    scoringStatus: data.scoringStatus,

    analystContext,

    // Keep the complete original data for Excel.
    reportData: data
  }
}];

/**
 * Parse Financial Analyst Response — v2
 * n8n Code node: Run Once for All Items
 * Expects the upstream node to be named "Prepare Financial Analyst Input".
 * Outputs the SAME report structure expected by the Python Excel generator.
 * The LLM supplies commentary only; the financial score and all numbers
 * are taken unmodified from the calculated reportData.
 */

const received = $input.all();
let source;
try {
  source = $('Prepare Financial Analyst Input').first().json;
} catch (error) {
  throw new Error('Cannot find node "Prepare Financial Analyst Input". Check its exact name and execute it first.');
}
const rawReport = source.reportData;
if (!rawReport || typeof rawReport !== 'object' || Array.isArray(rawReport)) {
  throw new Error('Financial source reportData is missing. Check Prepare Financial Analyst Input.');
}

const errors = [];
const warnings = [];
const asArray = x => Array.isArray(x) ? x : [];
const uniq = xs => [...new Set(xs.filter(Boolean))];
const text = x => typeof x === 'string' ? x.trim() : '';
const validNumber = x => typeof x === 'number' && Number.isFinite(x) ? x : null;
const human = x => String(x || '').replace(/_/g, ' ').replace(/\s+/g, ' ').trim();

function parseResponse(raw) {
  const content = raw.response ?? raw.message?.content ?? raw.data?.response
    ?? raw.output ?? raw.text ?? (raw.executive_summary ? raw : null);
  if (content === null || content === undefined) {
    throw new Error('No analyst response was returned by Ollama.');
  }
  if (typeof content === 'object' && !Array.isArray(content)) return content;
  if (typeof content !== 'string') throw new Error('Unexpected Ollama response type.');
  const clean = content.trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '').trim();
  try {
    return JSON.parse(clean);
  } catch (e) {
    const first = clean.indexOf('{');
    const last = clean.lastIndexOf('}');
    if (first < 0 || last <= first) throw new Error('No complete JSON object in response.');
    try {
      return JSON.parse(clean.slice(first, last + 1));
    } catch (_) {
      throw new Error('Analyst JSON invalid or truncated. Increase num_predict or shorten prompt.');
    }
  }
}

let parsed = {};
let successful = 0;
for (const item of received) {
  try {
    const obj = parseResponse(item.json || {});
    if (!obj || typeof obj !== 'object' || Array.isArray(obj)) {
      throw new Error('Analyst response is not an object.');
    }
    if (!successful) parsed = obj;
    successful++;
    if ((item.json || {}).done_reason === 'length') {
      warnings.push('Ollama hit the token limit; review narrative completeness.');
    }
  } catch (err) {
    errors.push(err.message);
  }
}
if (successful > 1) warnings.push('Multiple analyst responses received; first usable response selected.');

function findings(items) {
  return asArray(items).filter(x => x && typeof x === 'object')
    .map(x => ({title: text(x.title), explanation: text(x.explanation)}))
    .filter(x => x.title && x.explanation).slice(0, 6);
}
const PRIORITIES = ['high', 'medium', 'low'];
function recommendationList(items) {
  return asArray(items).filter(x => x && typeof x === 'object')
    .map(x => {
      const p = String(x.priority || '').trim().toLowerCase();
      return {
        title: text(x.title),
        explanation: text(x.explanation),
        priority: PRIORITIES.includes(p) ? p : 'medium'
      };
    })
    .filter(x => x.title && x.explanation)
    // high priority first, keep the model's order inside a priority
    .sort((a, b) => PRIORITIES.indexOf(a.priority) - PRIORITIES.indexOf(b.priority))
    .slice(0, 5);
}

const analysis = {
  headline: text(parsed.headline),
  executive_summary: text(parsed.executive_summary),
  overall_assessment: text(parsed.overall_assessment),
  strengths: findings(parsed.strengths),
  weaknesses: findings(parsed.weaknesses),
  financial_trends: findings(parsed.financial_trends),
  risk_factors: findings(parsed.risk_factors),
  recommendations: recommendationList(parsed.recommendations),
  score_explanation: text(parsed.score_explanation),
  data_limitations: asArray(parsed.data_limitations).map(text).filter(Boolean),
  conclusion: text(parsed.conclusion)
};

const mustHave = ['executive_summary','overall_assessment','score_explanation','conclusion'];
for (const field of mustHave) {
  if (!analysis[field]) errors.push(`Missing required analyst section: ${field}`);
}
if (!analysis.headline) warnings.push('Analyst headline missing; the workbook will build one from the score.');
if (!analysis.recommendations.length) warnings.push('Analyst gave no recommendations; the workbook will show rule-based next steps.');
const proseForLint = [analysis.headline, analysis.executive_summary, analysis.overall_assessment,
  analysis.score_explanation, analysis.conclusion,
  ...[...analysis.strengths, ...analysis.weaknesses, ...analysis.financial_trends,
      ...analysis.risk_factors, ...analysis.recommendations].map(x => x.explanation)].join(' ');
if (/(?<![\d.])0\.\d{4,}/.test(proseForLint)) {
  warnings.push('Analyst text contains long raw decimals; the workbook converts them to percentages.');
}
for (const field of ['strengths','weaknesses','financial_trends','risk_factors','recommendations']) {
  if (!Array.isArray(parsed[field])) warnings.push(`Analyst ${field} array was absent or malformed.`);
}

// The model must never be the source of these numbers.
const score = validNumber(rawReport.financialHealthScore);
const coverage = validNumber(rawReport.dataCoveragePercent);
if (score === null || score < 0 || score > 100) errors.push('Upstream financial health score missing or outside 0–100.');
if (coverage === null || coverage < 0 || coverage > 100) errors.push('Upstream scoring coverage missing or outside 0–100.');
if (rawReport.scoringStatus === 'blocked') errors.push('Upstream financial scoring is blocked.');
if (asArray(rawReport.errors).length) errors.push('Upstream report contains calculation/data errors; review before distribution.');
const failed = asArray(rawReport.validationChecks).filter(x =>
  x && ['failed', 'error'].includes(String(x.status || '').toLowerCase()));
if (failed.length) errors.push(`${failed.length} financial validation check(s) failed.`);

// Flag obvious incorrect score/coverage quotes in the narrative.
// This does NOT rewrite or invent financial figures.
const narrative = [analysis.executive_summary, analysis.overall_assessment,
  analysis.score_explanation, analysis.conclusion].join(' ');
function checkMention(regex, correct, label) {
  if (correct === null) return;
  const match = narrative.match(regex);
  if (match && Math.abs(Number(match[1]) - correct) > 0.11) {
    errors.push(`${label} in analyst prose (${match[1]}) differs from verified source (${correct}).`);
  }
}
checkMention(/financial\s+health\s+score\s+(?:of\s+|is\s+)?(\d+(?:\.\d+)?)/i, score, 'Financial health score');
checkMention(/data\s+coverage\s+(?:of\s+|is\s+)?(\d+(?:\.\d+)?)\s*%/i, coverage, 'Data coverage');

// Deterministic guidance for the workbook's dashboard.
// Rankings refer ONLY to the model's category scores, not actual credit grades.
const categories = asArray(rawReport.scoreCategories).filter(x => x && typeof x === 'object');
const scored = categories.filter(x => validNumber(x.score) !== null)
  .sort((a, b) => a.score - b.score);
const lowest = scored[0] || null;
const highest = scored.length ? scored[scored.length - 1] : null;
const notScored = categories.filter(x => validNumber(x.score) === null)
  .map(x => human(x.name || x.category));
const dashboardInsights = {
  scoreExplanation: 'This is a provisional, illustrative model score out of 100, NOT a credit rating.',
  coverageExplanation: 'Coverage measures the scoring inputs available, not the percentage of all financial information received.',
  mainWatchArea: lowest ? {
    category: human(lowest.name || lowest.category),
    score: lowest.score,
    explanation: 'Lowest scored category in the prototype model; review its underlying metrics.'
  } : null,
  relativeStrength: highest ? {
    category: human(highest.name || highest.category),
    score: highest.score,
    explanation: 'Highest scored category in the same model; does not establish that the business is financially safe.'
  } : null,
  notAssessed: notScored
};

const report = {
  company: rawReport.company ?? source.company ?? null,
  financialHealthScore: score,
  scoreRating: rawReport.scoreRating ?? null,
  dataCoveragePercent: coverage,
  scoringStatus: rawReport.scoringStatus ?? 'unknown',
  scoringProfile: rawReport.profile ?? null,
  scoreModel: rawReport.scoreModel ?? null,
  latestPeriods: rawReport.latestPeriods ?? {},
  scoreCategories: rawReport.scoreCategories ?? [],
  scoringMethod: rawReport.scoringMethod ?? {},
  financialAnalysis: analysis,
  dashboardInsights,
  financialMetrics: rawReport.financialMetrics ?? [],
  financialTrends: rawReport.financialTrends ?? [],
  consolidatedStatements: rawReport.consolidatedStatements ?? [],
  validationChecks: rawReport.validationChecks ?? [],
  warnings: uniq([...asArray(rawReport.warnings), ...warnings]),
  errors: uniq([...asArray(rawReport.errors), ...errors])
};
const ready = successful > 0 && errors.length === 0 &&
  asArray(report.scoreCategories).length > 0 &&
  (asArray(report.consolidatedStatements).length > 0 || asArray(report.financialMetrics).length > 0);

return [{json: {
  reportStatus: ready ? 'ready' : 'review_required',
  readyForExcelGeneration: ready,
  company: report.company,
  financialHealthScore: score,
  dataCoveragePercent: coverage,
  financialAnalysis: analysis,
  dashboardInsights,
  summary: {
    llmResponsesReceived: received.length,
    llmResponsesParsed: successful,
    strengths: analysis.strengths.length,
    weaknesses: analysis.weaknesses.length,
    financialTrends: analysis.financial_trends.length,
    riskFactors: analysis.risk_factors.length,
    recommendations: analysis.recommendations.length,
    narrativeComplete: mustHave.every(k => Boolean(analysis[k])),
    scoreAvailable: score !== null
  },
  report,
  warnings: report.warnings,
  errors: report.errors
}}];

const input = $input.item.json;

// ============================================
// 1. HELPERS
// ============================================

const warnings = [];
const errors = [];
const validations = [];

const TARGET_TYPES = [
  "balance_sheet",
  "income_statement",
  "cash_flow_statement"
];

const ALLOWED_TYPES = [
  ...TARGET_TYPES,
  "other_financial_statement"
];

const ALLOWED_STATUSES = [
  "extracted",
  "partial",
  "no_relevant_statements",
  "unreadable"
];

const ALLOWED_PERIOD_TYPES = [
  "as_of",
  "full_year",
  "quarter",
  "half_year",
  "year_to_date",
  "other",
  "unknown"
];

function unique(arr) {
  return [...new Set(arr)];
}

// Recognize alternative names for major financial totals.
// Never treat "total liabilities and equity" as equity.
const TOTAL_ALIASES = {
  total_assets: [
    "total_assets"
  ],
  total_liabilities: [
    "total_liabilities"
  ],
  total_equity: [
    "total_equity",
