      const difference =
        Math.round(
          (assets - liabilities - equity) * 100
        ) / 100;

      const allInteger =
        [assets, liabilities, equity].every(
          Number.isInteger
        );

      const tolerance =
        allInteger &&
        Math.max(
          Math.abs(assets),
          Math.abs(liabilities),
          Math.abs(equity)
        ) >= 1000
          ? 1
          : 0.01;

      const status =
        Math.abs(difference) < 0.000001
          ? "passed"
          : Math.abs(difference) <= tolerance
            ? "rounding_difference"
            : "failed";

      validations.push({
        statementType: type,
        periodID: id,
        check: "accounting_equation",
        totalAssets: assets,
        totalLiabilities: liabilities,
        totalEquity: equity,
        difference,
        tolerance,
        status
