const warnings = [];
const errors = [];
const validations = [];

const TARGET_TYPES = [
  "balance_sheet",
  "income_statement",
  "cash_flow_statement"
];

const ALLOWED_TYPES = [
  ...TARGET_TYPES,
  "other_financial_statement"
];

const ALLOWED_STATUSES = [
  "extracted",
  "partial",
  "no_relevant_statements",
  "unreadable"
];

const ALLOWED_PERIOD_TYPES = [
  "as_of",
  "full_year",
  "quarter",
  "half_year",
  "year_to_date",
  "other",
  "unknown"
];

function unique(arr) {
  return [...new Set(arr)];
}

// Recognize alternative names for major financial totals.
// Never treat "total liabilities and equity" as equity.
const TOTAL_ALIASES = {
  total_assets: [
    "total_assets"
  ],
  total_liabilities: [
    "total_liabilities"
  ],
  total_equity: [
    "total_equity",
    "total_shareholders_equity",
    "total_stockholders_equity",
    "shareholders_equity",
    "stockholders_equity",
    "total_shareholder_equity",
    "shareholder_equity",
    "shareholders_equity_total",
    "total_equity_attributable_to_shareholders"
  ]
};

function canonicalKey(key) {
  return String(key || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");
}

function validDate(value) {
  if (typeof value !== "string") return false;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;

  const date = new Date(value + "T00:00:00Z");

  return !Number.isNaN(date.getTime()) &&
    date.toISOString().slice(0, 10) === value;
}

function parseNumber(value) {
  if (
    value === null ||
    value === undefined ||
    value === ""
  ) {
    return { value: null, valid: true };
  }

  if (typeof value === "number") {
    return {
      value: Number.isFinite(value) ? value : null,
      valid: Number.isFinite(value)
    };
  }

  if (typeof value !== "string") {
    return { value: null, valid: false };
  }

  let text = value.trim();
  const negative = /^\(.*\)$/.test(text);

  if (negative) {
    text = text.slice(1, -1).trim();
  }

  text = text.replace(/,/g, "");

  if (!/^[+-]?\d+(\.\d+)?$/.test(text)) {
    return { value: null, valid: false };
  }

  const number = Number(text);

  return {
    value: negative ? -Math.abs(number) : number,
    valid: Number.isFinite(number)
  };
}

function finish(documentStatus, statements, rejectionReason) {
  const targetStatements = statements.filter(s =>
    TARGET_TYPES.includes(s.statement_type)
  );

  const detectedTypes = unique(
    targetStatements.map(s => s.statement_type)
  );

  const accountCount = statements.reduce(
    (sum, s) => sum + s.line_items.length,
    0
  );

  const periodCount = statements.reduce(
    (sum, s) => sum + s.periods.length,
    0
  );

  const checksPassed = validations.filter(
    v => v.status === "passed"
  ).length;

  const checksFailed = validations.filter(
    v => v.status === "failed"
  ).length;

  const hasUsableData = targetStatements.some(s =>
    s.periods.length > 0 &&
    s.line_items.some(item =>
      Object.values(item.values).some(
        value => typeof value === "number"
      )
    )
  );

  let extractionStatus = "ready";

  if (documentStatus === "no_relevant_statements") {
    extractionStatus = "rejected";
  } else if (documentStatus === "unreadable") {
    extractionStatus = "unreadable";
  } else if (errors.length > 0 || !hasUsableData) {
    extractionStatus = "review_required";
  } else if (
    documentStatus === "partial" ||
    warnings.length > 0
  ) {
    extractionStatus = "review_recommended";
  }

  const extractionSuccessful =
    hasUsableData &&
    errors.length === 0 &&
    documentStatus === "extracted";

  return {
    json: {
      company: data?.company ?? null,
      documentStatus,
      containsRelevantFinancialData:
        targetStatements.length > 0,
      detectedStatementTypes: detectedTypes,
      statements,
      extractionStatus,
      extractionSuccessful,
      usableFinancialData: hasUsableData,

      summary: {
        totalStatements: statements.length,
        targetStatements: targetStatements.length,
        totalPeriods: periodCount,
        totalAccounts: accountCount,
        balanceSheets: statements.filter(
          s => s.statement_type === "balance_sheet"
        ).length,
        incomeStatements: statements.filter(
          s => s.statement_type === "income_statement"
        ).length,
        cashFlowStatements: statements.filter(
          s => s.statement_type === "cash_flow_statement"
        ).length,
        checksPassed,
        checksFailed,
        warningCount: unique(warnings).length,
        errorCount: unique(errors).length
