        Math.round(
          (assets - liabilities - equity) * 100
        ) / 100;

      const allInteger =
        [assets, liabilities, equity].every(
          Number.isInteger
        );

      const tolerance =
        allInteger &&
        Math.max(
          Math.abs(assets),
          Math.abs(liabilities),
          Math.abs(equity)
        ) >= 1000
          ? 1
          : 0.01;

