        Math.abs(difference) < 0.000001
          ? "passed"
          : Math.abs(difference) <= tolerance
            ? "rounding_difference"
            : "failed";

      validations.push({
        statementType: type,
        periodID: id,
        check: "accounting_equation",
        totalAssets: assets,
        totalLiabilities: liabilities,
        totalEquity: equity,
        difference,
        tolerance,
        status
