  // 7. VALIDATE FINANCIAL ACCOUNTS
  // ==========================================

  const lineItems = [];
  const seenKeys = new Set();

  for (const item of statement.line_items) {
    if (!item || typeof item !== "object") {
      warnings.push(`${type}: malformed account.`);
      continue;
    }

    const key = String(item.key || "").trim();

    if (!key) {
      warnings.push(`${type}: account missing key.`);
      continue;
    }

    if (seenKeys.has(key)) {
      errors.push(
        `${type}: duplicate account key "${key}".`
      );
      continue;
    }

    seenKeys.add(key);

