}

const documentStatus = data.document_status;

if (!ALLOWED_STATUSES.includes(documentStatus)) {
  errors.push(
    `Invalid document_status: ${documentStatus}`
  );
}

if (!Array.isArray(data.statements)) {
  errors.push("Missing statements array.");

  return finish(
    "unreadable",
    [],
    "LLM output is missing its statements array."
  );
}

// ============================================
// 4. HANDLE IRRELEVANT DOCUMENTS
// ============================================

if (
  documentStatus === "no_relevant_statements" ||
  documentStatus === "unreadable"
) {
  if (data.statements.length > 0) {
    warnings.push(
      "Document marked irrelevant/unreadable but " +
      "contains statement entries. Review classification."
    );
  }

  return finish(
    documentStatus,
    [],
    data.rejection_reason ??
    "No usable financial statements identified."
  );
}

// ============================================
// 5. PROCESS EVERY FINANCIAL STATEMENT
// ============================================

const cleanedStatements = [];
let totalRawAccounts = 0;

for (const [statementIndex, statement] of
     data.statements.entries()) {

  if (!statement || typeof statement !== "object") {
    errors.push("Malformed financial statement skipped.");
    continue;
  }

  const type = statement.statement_type;

  if (!ALLOWED_TYPES.includes(type)) {
    warnings.push(
      `Unknown statement type: ${type}`
    );
    continue;
  }

  if (
    !Array.isArray(statement.periods) ||
    !Array.isArray(statement.line_items)
  ) {
    errors.push(
      `${type}: missing periods or line_items array.`
    );
    continue;
  }

  totalRawAccounts += statement.line_items.length;

  // ==========================================
  // 6. NORMALIZE REPORTING PERIODS
  // ==========================================

  const periods = [];
  const periodIDs = new Set();

  for (const period of statement.periods) {
    if (!period || typeof period !== "object") {
      warnings.push(`${type}: malformed period.`);
      continue;
    }

    const id = String(period.period_id || "").trim();

    if (!id) {
      errors.push(`${type}: missing period_id.`);
      continue;
    }

    if (periodIDs.has(id)) {
      warnings.push(
        `${type}: duplicate period ID ${id}`
      );
      continue;
    }

    const startDate = period.start_date ?? null;
    const endDate = period.end_date ?? null;

    if (startDate !== null && !validDate(startDate)) {
      errors.push(`${type}: invalid start date for ${id}`);
      continue;
    }

    if (endDate !== null && !validDate(endDate)) {
      errors.push(`${type}: invalid end date for ${id}`);
      continue;
    }

    if (startDate && endDate && startDate > endDate) {
      errors.push(`${type}: reversed dates for ${id}`);
      continue;
    }

    const periodType = period.period_type || "unknown";

    if (!ALLOWED_PERIOD_TYPES.includes(periodType)) {
      warnings.push(
        `${type}: unknown period type for ${id}`
      );
    }

    if (
      type === "balance_sheet" &&
      periodType !== "as_of"
    ) {
      warnings.push(
        `Balance sheet period ${id} is not marked as_of.`
      );
    }

    if (!endDate) {
      warnings.push(
        `${type}: missing end date for ${id}`
      );
    }

    periodIDs.add(id);

    periods.push({
      period_id: id,
      label: String(period.label || id),
      period_type: periodType,
      start_date: startDate,
      end_date: endDate
    });
  }

  // ==========================================
  // 7. VALIDATE FINANCIAL ACCOUNTS
  // ==========================================

  const lineItems = [];
  const seenKeys = new Set();

  for (const item of statement.line_items) {
    if (!item || typeof item !== "object") {
      warnings.push(`${type}: malformed account.`);
      continue;
    }

    const key = String(item.key || "").trim();

    if (!key) {
      warnings.push(`${type}: account missing key.`);
      continue;
    }

    if (seenKeys.has(key)) {
      errors.push(
        `${type}: duplicate account key "${key}".`
      );
      continue;
    }

    seenKeys.add(key);

    const values = {};
    const originalValues =
      item.values &&
      typeof item.values === "object" &&
      !Array.isArray(item.values)
        ? item.values
        : {};

    for (const period of periods) {
      const id = period.period_id;
      const result = parseNumber(originalValues[id]);

      values[id] = result.value;

      if (!result.valid) {
        warnings.push(
          `${type}: invalid value for ${key}, ${id}`
        );
      }
    }

    const unknownPeriods = Object.keys(
      originalValues
    ).filter(id => !periodIDs.has(id));

    if (unknownPeriods.length) {
      warnings.push(
        `${type}: ${key} references unknown period IDs: ` +
        unknownPeriods.join(", ")
      );
    }

    const section = String(item.section || "");
    const subsection = String(item.subsection || "");

    // Allow common names for shareholder equity.
    // "total" is also a valid section for grand totals.
    if (
      type === "balance_sheet" &&
      ![
        "assets",
        "liabilities",
        "equity",
        "shareholder_equity",
        "shareholders_equity",
        "stockholder_equity",
        "stockholders_equity",
        "total"
      ].includes(canonicalKey(section))
    ) {
      warnings.push(
        `Balance sheet account ${key} has invalid section.`
      );
    }

    lineItems.push({
      key,
      label: String(item.label || key),
      section,
      subsection,
      values,
      source_page: item.source_page ?? null
    });
  }

  if (periods.length === 0) {
    errors.push(`${type}: no valid periods.`);
  }

  if (lineItems.length === 0) {
    errors.push(`${type}: no accounts extracted.`);
  }

  // ==========================================
  // 8. FINANCIAL VALIDATION
  // ==========================================

  function getAmount(key, periodID) {
    const account = lineItems.find(
      item =>
        (TOTAL_ALIASES[key] || [key]).includes(
          canonicalKey(item.key)
        )
    );

    return account?.values?.[periodID] ?? null;
  }

  if (type === "balance_sheet") {
    for (const period of periods) {
      const id = period.period_id;

      const assets = getAmount("total_assets", id);
      const liabilities =
        getAmount("total_liabilities", id);
      const equity = getAmount("total_equity", id);

      if (
        [assets, liabilities, equity].some(
          value => value === null
        )
      ) {
        validations.push({
          statementType: type,
          periodID: id,
          check: "accounting_equation",
          status: "missing_data",
          difference: null
        });

        warnings.push(
          `Balance sheet ${id}: missing major totals.`
        );

        continue;
      }

      const difference =
        Math.round(
          (assets - liabilities - equity) * 100
        ) / 100;

      const allInteger =
        [assets, liabilities, equity].every(
          Number.isInteger
        );

      const tolerance =
        allInteger &&
        Math.max(
          Math.abs(assets),
          Math.abs(liabilities),
          Math.abs(equity)
        ) >= 1000
          ? 1
          : 0.01;

      const status =
        Math.abs(difference) < 0.000001
          ? "passed"
          : Math.abs(difference) <= tolerance
            ? "rounding_difference"
            : "failed";

      validations.push({
        statementType: type,
        periodID: id,
        check: "accounting_equation",
        totalAssets: assets,
        totalLiabilities: liabilities,
        totalEquity: equity,
        difference,
        tolerance,
        status
      });

      if (status === "rounding_difference") {
        warnings.push(
          `Balance sheet ${id}: accounting equation ` +
          `differs by ${difference} source unit(s), ` +
          `possible rounding.`
        );
      } else if (status === "failed") {
        errors.push(
          `Balance sheet ${id}: accounting equation ` +
          `failed by ${difference}.`
        );
      }
    }
  }

  // ==========================================
  // 9. STORE CLEAN STATEMENT
  // ==========================================

  cleanedStatements.push({
    statement_type: type,
    company: statement.company ?? data.company ?? null,
    currency: statement.currency ?? null,
    unit_multiplier: statement.unit_multiplier ?? null,
    periods,
    line_items: lineItems,
    warnings: Array.isArray(statement.warnings)
      ? unique(statement.warnings.map(String))
      : [],
    source_statement_index: statementIndex
  });

  if (Array.isArray(statement.warnings)) {
    warnings.push(...statement.warnings.map(String));
  }
}

// ============================================
// 10. DETECT POSSIBLE LLM REPETITION
// ============================================

if (totalRawAccounts > 1500) {
  errors.push(
    "Unusually large LLM output: possible repetition."
  );
}

if (data.statements.length > 20) {
  errors.push(
    "Unusually many financial statements returned."
  );
}

const statementSignatures = new Set();

for (const statement of cleanedStatements) {
  const signature = JSON.stringify({
    type: statement.statement_type,
    company: statement.company,
    periods: statement.periods,
    line_items: statement.line_items
  });

  if (statementSignatures.has(signature)) {
    errors.push(
      `Repeated identical ${statement.statement_type} detected.`
    );
  }

  statementSignatures.add(signature);
}

const actualTypes = unique(
  cleanedStatements
    .filter(s => TARGET_TYPES.includes(s.statement_type))
    .map(s => s.statement_type)
);

if (Array.isArray(data.detected_statement_types)) {
  const declaredTypes = unique(
    data.detected_statement_types
  );

  if (
    JSON.stringify([...declaredTypes].sort()) !==
    JSON.stringify([...actualTypes].sort())
  ) {
    warnings.push(
      "Detected statement types do not match " +
      "extracted statements."
    );
  }
}

// ============================================
// 11. FINAL CLEAN OUTPUT
// ============================================

if (cleanedStatements.length === 0) {
  errors.push("No valid financial statements extracted.");
}

return finish(
  documentStatus === "partial" ? "partial" : "extracted",
  cleanedStatements,
  data.rejection_reason ?? null
);
